package com.kgsoft.favorsbank.data

/**
 * Official (non-machine) translations of every religious text in the app.
 *
 * For each text: [arabic] is the fixed original, [transliteration] a Latin
 * pronunciation guide shared by all languages (empty when the source provides
 * none — the UI then hides that line), [translations] the official meaning
 * per language, [sources] the per-language source citation.
 * Missing languages fall back English -> Arabic; never blank, never broken.
 */
data class SacredText(
    val arabic: String,
    val transliteration: String,
    val transliterations: Map<String, String> = emptyMap(),
    val translations: Map<String, String>,
    val sources: Map<String, String> = emptyMap(),
) {
    fun translit(lang: String): String =
        transliterations[lang] ?: transliterations["en"] ?: transliteration
    fun meaning(lang: String): String =
        translations[lang] ?: translations["en"] ?: arabic
    fun source(lang: String): String =
        sources[lang] ?: sources["en"] ?: ""
}

