        transliteration = "",
        translations = mapOf("en" to "Glorified is Allah and praised is He, Glorified is Allah the Most Great.", "fr" to "Gloire à Allah et qu'Il soit loué. Gloire à Allah, Allah est Le Suprême.", "ur" to "میں اللہ کی پاکیزگی بیان کرتا ہوں اس کی تعریف کے ساتھ", "id" to "Maha Suci Allah dan segala puji (bagi-Nya)", "fa" to "الله پاک و منزه است، و او را ستایش میکنم، خداوند عظیم، پاک و منزه است", "sw" to "Ametakasika Mwenyezi Mungu, na sifa njema zote nizake, Ametakasika Mwenyezi Mungu aliye Mtukufu", "ha" to "Tsarki ya tabbata ga Allah da godiyarsa, kuma tsarki ya tabbata ga Allah mai girma", "bn" to "আল্লাহর প্রশংসাসহকারে তাঁর পবিত্রতা ও মহিমা বর্ণনা করছি। মহান আল্লাহর পবিত্রতা ও মহিমা ঘোষণা করছি", "tr" to "Allah'a hamd ederek O'nu tüm noksanlıklardan tenzih ederim. Yüce Allah'ı tüm noksanlıklardan tenzih ederim"),
