val ZIKR_I18N: Map<String, SacredText> = mapOf(
    "(اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ)" to SacredText(
        arabic = "(اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ)",
        transliteration = "Allāhu lā ilāha illā huwal-hayyul-qayyūm. Lā ta'khudhuhū sinatun wa lā nawm. Lahū mā fis-samāwāti wa mā fil-ard. Man dhalladhī yashfa'u 'indahū illā bi-idhnih. Ya'lamu mā baina aidīhim wa mā khalfahum. Wa lā yuhītūna bishay'in min 'ilmihī illā bimā shā'. Wasi'a kursiyyuhus-samāwāti wal-ard. Wa lā ya'ūduhū hifzuhumā. Wa huwal-'aliyyul-'azīm.",
        transliterations = mapOf("bn" to "আল্লা-হু লা ইলা-হা ইল্লা হুওয়াল হাইয়্যূল কাইয়্যূমু লা তা’খুযুহু সিনাতুাঁও ওয়ালা নাউম। লাহূ মা-ফিসসামা-ওয়া-তি ওয়ামা ফিল আরদ্বি। মান যাল্লাযী ইয়াশফা‘উ ‘ইনদাহূ ইল্লা বিইযনিহী। ইয়া‘লামু মা বাইনা আইদীহিম ওয়ামা খালফাহুম। ওয়ালা ইয়ুহীতূনা বিশাইইম মিন্ ইলমিহী ইল্লা বিমা শাআ। ওয়াসি‘আ কুরসিয়্যুহুস সামা-ওয়া-তি ওয়াল আরদ্ব। ওয়ালা ইয়াউদুহূ হিফযুহুমা ওয়া হুয়াল ‘আলিয়্যূল ‘আযীম"),
        translations = mapOf("en" to "Allah! There is none worthy of worship but He, the Ever-Living, the One Who sustains and protects all that exists. Neither slumber nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them in this world, and what will happen to them in the Hereafter. And they will never encompass anything of His Knowledge except that which He wills. His Throne extends over the heavens and the earth, and He feels no fatigue in guarding and preserving them. And He is the Most High, the Most Great.", "ur" to "خدا (وہ معبود برحق ہے کہ) اس کے سوا کوئی عبادت کے لائق نہیں زندہ ہمیشہ رہنے والا اسے نہ اونگھ آتی ہے نہ نیند جو کچھ آسمانوں میں اور جو کچھ زمین میں ہیں سب اسی کا ہے کون ہے جو اس کی اجازت کے بغیر اس سے (کسی کی) سفارش کر سکے جو کچھ لوگوں کے روبرو ہو رہا ہے اور جو کچھ ان کے پیچھے ہوچکا ہے اسے سب معلوم ہے اور وہ اس کی معلومات میں سے کسی چیز پر دسترس حاصل نہیں کر سکتے ہاں جس قدر وہ چاہتا ہے (اسی قدر معلوم کرا دیتا ہے) اس کی بادشاہی (اور علم) آسمان اور زمین سب پر حاوی ہے اور اسے ان کی حفاظت کچھ بھی دشوار نہیں وہ بڑا عالی رتبہ اور جلیل القدر ہے", "id" to "Allah, tidak ada Tuhan (yang berhak disembah), melainkan Dia yang hidup kekal, lagi terus menerus mengurus (makhluk-Nya). Tidak mengantuk dan tidak tidur. Kepunyaan-Nya apa yang di langit dan di bumi. Tiada yang dapat memberi syafa'at di sisi Allah tanpa seizin-Nya. Allah mengetahui apa-apa yang ada di hadapan mereka dan di belakang mereka. Dan mereka tidak mengetahui apa-apa dari ilmu Allah, melainkan apa yang dikehendaki-Nya. Kursi Allah meliputi langit dan bumi. Dan Allah tidak merasa berat memelihara keduanya. Dan Allah Maha Tinggi lagi Maha Besar.", "fa" to "خداوند هیچ معبودی »به حق« جز او نیست، خداوندی که زنده و قائم به ذات خویش است، هیچ گاه خواب سبک و سنگین او را فرا نمیگیرد، برای اوست آنچه در آسمانھا و زمین است، کیست که نزد او جز به فرمانش شفاعت کند، آنچه را پیش روی آنھا »بندگان« و پشت سر آنھاست میداند، و از گذشته و آیندۀ آنان آ گاه است، آنھا جز به مقداری که او بخواهد احاطه به علم او ندارند، کرسی او آسمانھا و زمین را دربر گرفته و حفظ و نگھداری آسمان و زمین برای او گران نیست، و او بلند مرتبه و باعظمت است", "ha" to "“Allah, babu wani abin bautawa da cancanta sai shi, Rayayye, mai tsayuwa da komai, gyangyadi ba ya kamashi kuma macci baya kamashi, shi ke da abinda ya ke cikin sammai da abinda ke cikin kassai, wanene yake 51 yin ceto awurinsa sai dai da izininsa? Yana sane da abinda yake gaban su da abinda ke bayan su, kuma ba su kewayewa da komai daga ilimi sa, saidai da abinda ya so, Kursiyin sa ya yalwaci sammai da kassai, Kuma shi ne madaukaki mai girma”. Suratul Bakara, aya ta: 255.", "bn" to "আল্লাহ, তিনি ছাড়া কোনো সত্য ইলাহ্ নেই। তিনি চিরঞ্জীব, সর্বসত্তার ধারক। তাাঁকে তন্দ্রাও স্পর্শ করতে পারে না, নিদ্রাও নয়। আসমানসমূহে যা রয়েছে ও যমীনে যা রয়েছে সবই তাঁর। কে সে, যে তাঁর অনুমতি ব্যতীত তাঁর কাছে সুপারিশ করবে? তাদের সামনে ও পিছনে যা কিছু আছে তা তিনি জানেন। আর যা তিনি ইচ্ছে করেন তা ছাড়া তাঁর জ্ঞানের কোনো কিছুকেই তারা পরিবেষ্টন করতে পারে না। তাঁর ‘কুরসী’ আসমানসমূহ ও যমীনকে পরিব্যাপ্ত করে আছে; আর এ দু’টির রক্ষণাবেক্ষণ তাঁর জন্য বোঝা হয় না। আর তিনি সুউচ্চ সুমহান।", "tr" to "Allah, O'ndan başka hak ilah olmayan, kendisini uyuklama ve uyku tutmayan, Hayy, Kayyûm'dur (her an yarattıklarınızı gözetleyendir).Göklerde ve yerde ne varsa O'nundur.O'nun izni olmadan katında şefaat edecek kimdir? Onların işlediklerini, işleyeceklerini bilir. O'nun dilediğinden başka ilminden hiçbir şeyi kavrayamazlar. Kürsüsü gökleri ve yeri kuşatmıştır. Göklerin ve yerin gözetilmesi O'na ağır gelmez. O yücedir, büyüktür."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "(قُلْ هُوَ اللَّهُ أَحَدٌ ◇ اللَّهُ الصَّمَدُ ◇ لَمْ يَلِدْ وَلَمْ يُولَدْ ◇ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ◇)" to SacredText(
        arabic = "﷽\n\n(قُلْ هُوَ اللَّهُ أَحَدٌ ◇ اللَّهُ الصَّمَدُ ◇ لَمْ يَلِدْ وَلَمْ يُولَدْ ◇ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ ◇)",
        transliteration = "Qul huwallāhu ahad. Allāhus-samad. Lam yalid wa lam yūlad. Wa lam yakul-lahū kufuwan ahad.",
        transliterations = mapOf("bn" to "ক্বল ু হুওয়াল্লা-হু আহাদ। আল্লাহুস্ সামাদ। লাম ইয়ালিদ ওয়া লাম ইউলাদ। ওয়া লাম ইয়াকুল্লাহু কুফুওয়ান আহাদ"),
        translations = mapOf("en" to "With the Name of Allah, the Most Gracious, the Most Merciful. Say: He is Allah (the) One. The Self-Sufficient Master, Whom all creatures need, He begets not nor was He begotten, and there is none equal to Him. With the Name of Allah, the Most Gracious, the Most Merciful.", "ur" to "کہو کہ وہ (ذات پاک جس کا نام) الله (ہے) ایک ہے۔ معبود برحق جو بےنیاز ہے۔ نہ کسی کا باپ ہے اور نہ کسی کا بیٹا۔ اور کوئی اس کا ہمسر نہیں۔", "id" to "Katakanlah (Muhammad), \"Dialah Allah, Yang Maha Esa. Allah tempat meminta segala sesuatu. (Allah) tidak beranak dan tidak pula diperanakkan. Dan tidak ada sesuatu yang setara dengan Dia.\"", "fa" to "به نام خداوند بخشنده ی مھربان (بگو خدا یگانه است، خدا، کمال مطلق و سرور والای برآورندۀ امیدها و برطرفکنندۀ نیازمندیھا است، نه زاده، و نه زاده شده است، و نه همتایی دارد", "ha" to "Da sunan Allah mai yawan rahama mai yawan jin kai. 1. Ka ce; Shi ne Allah shi kadai. 2. Allah wanda ake nufata da dukkanin bukatu. 3. Bai haifa ba kuma ba’a haifeshi ba. 4. Kuma wani bai kasance kini a gare shi ba. 52", "bn" to "বলুন, তিনি আল্লাহ, এক-অদ্বিতীয়। আল্লাহ হচ্ছেন ‘সামাদ’ (তিনি কারো মুখাপেক্ষী নন, সকলেই তাঁর মুখাপেক্ষী)। তিনি কাউকেও জন্ম দেন নি এবং তাাঁকেও জন্ম দেওয়া হয় নি। আর তাঁর সমতুল্য কেউই নেই।", "tr" to "De ki: O Allah birdir. Allah Samed'dir, (her şeyden müstağnidir ve her şey O'na muhtaçtır).O doğurmamış ve doğmamıştır. Hiçbir şey O'na denk değildir."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ◇ مِنْ شَرِّ مَا خَلَقَ ◇ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ◇ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ◇ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ◇" to SacredText(
        arabic = "﷽\nقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ◇ مِنْ شَرِّ مَا خَلَقَ ◇ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ◇ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ◇ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ ◇",
        transliteration = "Qul a'ūdhu birabbil-falaq. Min sharri mā khalaq. Wa min sharri ghāsiqin idhā waqab. Wa min sharrin-naffāthāti fil-'uqad. Wa min sharri hāsidin idhā hasad.",
        transliterations = mapOf("bn" to "ক্বুল আ‘উযু বিরব্বিল ফালাক্ব। মিন শাররি মা খালাক্ব। ওয়া মিন শাররি গাসিক্বিন ইযা ওয়াক্বাব। ওয়া মিন শাররিন নাফফা-সা-তি ফিল ‘উক্বাদ। ওয়া মিন শাররি হা-সিদিন ইযা হাসাদ"),
        translations = mapOf("en" to "Say: I seek refuge with (Allah) the Lord of the daybreak, from the evil of what He has created, and from the evil of the darkening (night) as it comes with its darkness, and from the evil of those who practice witchcraft when they blow in the knots, and from the evil of the envier when he envies. With the Name of Allah, the Most Gracious, the Most Merciful.", "ur" to "کہو کہ میں صبح کے پروردگار کی پناہ مانگتا ہوں۔ ہر چیز کی بدی سے جو اس نے پیدا کی۔ اور شب تاریکی کی برائی سے جب اس کا اندھیرا چھا جائے۔ اور گنڈوں پر (پڑھ پڑھ کر) پھونکنے والیوں کی برائی سے۔ اور حسد کرنے والے کی برائی سے جب حسد کرنے لگے۔", "id" to "Katakanlah, \"Aku berlindung kepada Tuhan yang menguasai subuh (fajar), dari kejahatan (makhluk yang) Dia ciptakan, dan dari kejahatan malam apabila telah gelap gulita, dan dari kejahatan (perempuan-perempuan) penyihir yang meniup pada buhul-buhul (talinya), dan dari kejahatan orang yang dengki apabila dia dengki.\"", "fa" to "به نام خداوند بخشنده ی مھربان (بگو پناه میبرم به خداوند سپیده دم. از شر آنچه آفریده است، و از شر شب بدانگاه که کاملا فرا میرسد، و از شر کسانی که در گرهها میدمند، و از شر حسود بدانگاه که حسد میورزد", "ha" to "Da sunan Allah mai yawan rahama mai yawan jin kai. 1. Ka ce; Ina neman tsari daga Ubangijin safiya. 2. (Ya tsare ni) daga sharrin abinda ya halitta. 3. Da kuma sharrin dare idan ya yi duhu. 4. Da kuma sharrin masu tofi akuduri (a kulli). 5. Da kuma sharrin mai hasada idan ya yi hasada. (Suratul Falak, aya ta: 1-5). 53", "bn" to "বলুন, আমি আশ্রয় প্রার্থনা করছি ঊষার রবের। তিনি যা সৃষ্টি করেছেন তার অনিষ্ট হতে। ‘আর অনিষ্ট থেকে রাতের অন্ধকারের, যখন তা গভীর হয়। আর অনিষ্ট থেকে সমস্ত নারীদের, যারা গিরায় ফুাঁক দেয়। আর অনিষ্ট থেকে হিংসুকের, যখন সে হিংসা করে।", "tr" to "De ki: Yarattıklarının şerrinden, bastırdığı zaman karanlığın şerrinden, düğümlere üfleyen büyücülerin şerrinden, hased ettiği zaman hasetçilerin şerrinden, tan yerini ağartan Rabbe sığınırım."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "قُلْ أَعُوذُ بِرَبِّ النَّاسِ ◇ مَلِكِ النَّاسِ ◇ إِلَٰهِ النَّاسِ ◇ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ◇ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ◇ مِنَ الْجِنَّةِ وَالنَّاسِ ◇" to SacredText(
        arabic = "﷽\nقُلْ أَعُوذُ بِرَبِّ النَّاسِ ◇ مَلِكِ النَّاسِ ◇ إِلَٰهِ النَّاسِ ◇ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ◇ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ◇ مِنَ الْجِنَّةِ وَالنَّاسِ ◇",
        transliteration = "Qul a'ūdhu birabbin-nās. Malikin-nās. Ilāhin-nās. Min sharril-waswāsil-khannās. Alladhī yuwaswisu fī sudūrin-nās. Minal-jinnati wan-nās.",
        transliterations = mapOf("bn" to "ক্বুল ‘আউযু বিরাব্বিন্না-স। মালিকিন্না-সি, ইলা-হিন্নাসি, মিন শাররিল ওয়াসওয়াসিল খান্না-স, আল্লাযি ইউওয়াসউইসু ফী সুদূরিন না-সি, মিনাল জিন্নাতি ওয়ান্না-স।"),
        translations = mapOf("en" to "Say: I seek refuge with (Allah) the Lord of mankind, the King of mankind, the God of mankind, from the evil of the whisperer who withdraws, who whispers in the breasts of mankind, of jinns and men.", "ur" to "کہو کہ میں لوگوں کے پروردگار کی پناہ مانگتا ہوں۔ (یعنی) لوگوں کے حقیقی بادشاہ کی۔ لوگوں کے معبود برحق کی۔ (شیطان) وسوسہ انداز کی برائی سے جو (خدا کا نام سن کر) پیچھے ہٹ جاتا ہے۔ جو لوگوں کے دلوں میں وسوسے ڈالتا ہے۔ وہ جنّات میں سے (ہو) یا انسانوں میں سے۔", "id" to "Katakanlah, \"Aku berlindung kepada Tuhannya manusia, Raja manusia, sembahan manusia, dari kejahatan (bisikan) setan yang bersembunyi, yang membisikkan (kejahatan) ke dalam dada manusia, dari (golongan) jin dan manusia.\"", "fa" to "به نام خداوند بخشندۀ مھربان، (بگو پناه میبرم به پروردگار مردمان، به مالک و حاکم »واقعی« مردم، به معبود »به حق« مردم، از شر وسوسهگری که واپس میرود، از وسوهگری است که در سنیههای مردم به وسوسه میپردازد، »در سینههای مردمانی« از جنها و انسانھا", "ha" to "Da sunan Allah mai yawan rahama mai yawan jin kai. 1. Ka ce; Ina neman tsari daga Ubangijin mutane. 2. Mamallakin mutane. 3. Abin bautar mutane. 4. (Ya tsare ni) daga sharrin maiwaswasi alkhannas. 5. Wanda yake waswasi a zukatan mutane. 6. Daga cikin aljanu yake da kuma mutane. (Suratun Nas, aya ta: 1-6).", "bn" to "বলুন, আমি আশ্রয় প্রার্থনা করছি মানুষের রবের, মানুষের অধিপতির, মানুষের ইলাহের কাছে, আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট থেকে; যে কুমন্ত্রণা দেয় মানুষের অন্তরে, জিন্নের মধ্য থেকে এবং মানুষের মধ্য থেকে।", "tr" to "De ki: İnsanlar ve cinlerden olup insanların göğüslerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Rabbi, insanların hükümdârı ve insanların ilahı olan Allah'a sığınırım."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "أصبحنا و أصبح الملك لله و الحمدلله، لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء، قدير ربي أسألك خير ما في هذا اليوم و خير ما بعده، و أعوذ بك من شر ما في هذا اليوم و شر ما بعده، رب أعوذ بك من الكسل و سوء الكبر، رب أعوذ بك من عذاب في النار و و عذاب في القبر" to SacredText(
        arabic = "أصبحنا و أصبح الملك لله و الحمدلله، لا إله إلا الله وحده لا شريك له له الملك وله الحمد وهو على كل شيء، قدير ربي أسألك خير ما في هذا اليوم و خير ما بعده، و أعوذ بك من شر ما في هذا اليوم و شر ما بعده، رب أعوذ بك من الكسل و سوء الكبر، رب أعوذ بك من عذاب في النار و و عذاب في القبر",
        transliteration = "((ASW-BAHNAA WA ASW-BAHAL-MULKU LILLAH, WAL-HAMDU LILLAH, LAA ILAAHA ILLA LLAHU WAHDAHU LAA SHARIIKA LAHU, LAHUL-MULKU WALAHUL-HAMDU WAHUWA ALA KULLI SHAY-IN QADIIR))",
        transliterations = mapOf("bn" to "আসবাহ্না ওয়া আসবাহাল মুলকু লিল্লাহি ওয়ালহাম্দু লিল্লাহি, লা ইলা-হা ইল্লাল্লা-হু ওয়াহ্দাহু লা শারীকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়াহুয়া আলা কুল্লি শাই’ইন ক্বাদীর। রব্বি আস্আলুকা খাইরা মা ফী হা-যাল ইয়াউমি ওয়া খাইরা মা বা‘দাহু, ওয়া আ‘ঊযু বিকা মিন শাররি মা ফী হা-যাল ইয়াউমি ওয়া শাররি মা বা‘দাহু। রব্বি আঊযু বিকা মিনাল কাসালি ওয়া সূইল-কিবারি। রবিব আ‘ঊযু বিকা মিন ‘আযাবিন ফিন্না-রি ওয়া আযাবিন্ ফিল ক্বাবরি"),
        translations = mapOf("en" to "We have entered a new day 1 and with it all dominion is Allah's. Praise is to Allah. None has the right to be worshipped but Allah alone, Who has no partner. To Allah belongs the dominion, and to Him is the praise and He is Able to do all things. My Lord, I ask You for the goodness of this day and of the days that come after it, and I seek refuge in You from the evil of this day and of the days that come after it.2 My Lord, I seek refuge in You from laziness and helpless old age. My Lord, I seek refuge in You from the punishment of Hell-fire, and from the punishment of the grave.3", "fr" to "Nous sommes au soir et la Royauté appartient à Dieu. Louange à Dieu. Il n'y a pas de divinité en dehors de Dieu, l'Unique sans associé. À Lui la Royauté et la Louange. Il est puissant sur toute chose. Seigneur je Te demande le bien de cette nuit et le bien qui vient après elle, et je me réfugie auprès de Toi contre le mal de cette nuit et le mal qui vient après elle. Seigneur je me réfugie auprès de Toi contre la paresse, la mauvaise vieillesse. Seigneur je me réfugie auprès de Toi contre le châtiment du feu et le châtiment de la tombe.", "ur" to "ہم نے صبح کی اور اللہ کے سارے ملک نے صبح کی اور سب تعریف اللہ ہی کے لیے ہے۔ اللہ کے سوا کوئی معبود نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اسی کی بادشاہت ہے اور اسی کے لیے سب تعریف ہے اور وہ ہر چیز پر کامل قدرت رکھتا ہے۔ اے میرے رب! میں تجھ سے اس دن کی بہتری کا سوال کرتا ہوں اور اس دن کی بہتری کا جو اس کے بعد آنے والا ہے اور میں اس دن کے شر سے تیری پناہ میں آتا ہوں اور اس کے بعد آنے والے دن کے شر سے۔ اے میرے رب! میں کاہلی اور بڑھاپے کی خرابی سے تیری پناہ میں آتا ہوں۔ اے میرے رب! میں آگ کے عذاب سے اور قبر کے عذاب سے تیری پناہ میں آتا ہوں۔", "id" to "Kami telah memasuki waktu pagi, kerajaan milik Allah, segala puji bagi Allah. Tidak ada Tuhan yang berhak disembah selain Allah Yang Maha Esa, tiada sekutu bagi-Nya. Bagi-Nya kerajaan dan bagi-Nya pujian. Dia-lah yang Maha Kuasa atas segala sesuatu. Ya Tuhanku, aku mohon kepada-Mu kebaikan hari ini dan kebaikan sesudahnya. Aku berlindung kepada-Mu dari kejahatan hari ini dan kejahatan sesudahnya. Wahai Tuhanku, aku berlindung kepada-Mu dari kemalasan dan kejelekan di hari tua. Wahai Tuhanku, aku berlindung kepada-Mu dari siksaan di neraka dan siksaan di kubur.", "fa" to "ما و تمام جھانیان، شب را برای خدا به صبح رسانیدیم، و حمد از آن خداست، هیچ معبودی، بجز الله »به حق« که یکتاست و شریکی ندارد وجود ندارد. پادشاهی و حمد فقط از آن اوست و او بر هر چیز قادر است. الھی! من خیر آنچه در این روز است و خیر آنچه بعد از آن است را از تو میطلبم، و از شر آنچه که در این روز و ما بعد آن، وجود دارد، به تو پناه میبرم. الھی! من از تنبلی و بدی های پیری به تو پناه میبرم، بار الھا! من از عذاب آتش و قبر به تو پناه میبرم", "sw" to "Tumeingia wakati wa asubuhi na umekuwa Ufalme ni wa Mwenyezi Mungu, na sifa njema ni za Mwenyezi Mungu, hapana mola apasae kuabudiwa kwa haki ila Mwenyezi Mungu, hali ya kuwa peke yake, hana mshirika, ni wake Ufalme, na ni zake sifa njema, na yeye juu ya kila kitu ni Mueza, Ewe Mola, na kuomba kheri ya siku ya leo, na kheri ya baada ya siku hii, na ninajilinda kwako kutokana na shari ya siku ya leo, na shari ya baada ya siku hii, Ewe Mola, najilinda kwako kutokana na uvivi, na ubaya wa uzee (uzee ubaya), Ewe Mola, najilinda kwako kutokana na adhabu ya moto, na adhabu ya kaburi", "ha" to "Mun wayi gari, kuma mulki ya wayi gari yana mai tabbata ga Allah, dukkan yabo ya tabbata ga Allah babu abin bauta da cancanta sai shi, shi kadai ba shi da abokin tarayya agare shi, mulki na sane kuma yabo na sane kuma shi akan komai mai iko ne. Ya Ubangiji ina rokonka alherin da ke cikin wannan ranar, kuma da alherin dake bayan ta, kuma ina neman tsarinka daga sharrin dake cikin wannan ranar da sharrin dake bayan ta. Ubangiji ina neman tsarinka da ka kareni daga kasala da kuma mumunan tsufa.Ya Ubangiji ina neman tsarinka daga azabar wuta da kuma azabar kabari. Idan kuma da maraice ne sai ya ce:", "bn" to "আমরা সকালে উপনীত হয়েছি, অনুরূপ যাবতীয় রাজত্বও সকালে উপনীত হয়েছে, আল্লাহর জন্য। সমুদয় প্রশংসা আল্লাহর জন্য। একমাত্র আল্লাহ ছাড়া কোনো হক্ব ইলাহ নেই, তাঁর কোনো শরীক নেই। রাজত্ব তাঁরই এবং প্রশংসাও তাঁর, আর তিনি সকল কিছুর ওপর ক্ষমতাবান। হে রব্ব! এই দিনের মাঝে এবং এর পরে যা কিছু কল্যাণ আছে আমি আপনার নিকট তা প্রার্থনা করি। আর এই দিনের মাঝে এবং এর পরে যা কিছু অকল্যাণ আছে, তা থেকে আমি আপনার আশ্রয় চাই। হে রব্ব! আমি আপনার কাছে আশ্রয় চাই অলসতা ও খারাপ বার্ধক্য থেকে। হে রব্ব! আমি আপনার কাছে আশ্রয় চাই জাহান্নামে আযাব হওয়া থেকে এবং কবরে আযাব হওয়া থেকে।", "tr" to "Mülk, devamlı Allah'a âit bir halde sabahladık. Hamd Allah'adır. Allah'tan başka hak ilah yoktur. O, tektir ve ortağı yoktur. Mülk O'nundur. Hamd da O'nadır. O, her şeye gücü yetendir. Rabbim! Senden bu günde ve bu günden sonra iyiliklerini isterim; bu günün şerrinden ve bu günden sonra (meydana gelecek olan) şerden de sana sığınırım. Rabbim! Tembellikten ve (aklını yitirmek ve bunamak gibi) kötü yaşlılıktan sana sığınırım. Rabbim! Cehennem ve kabir azabından sana sığınırım."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "fr" to "La Citadelle du Musulman, Min. des Affaires islamiques (Riyad), 2005, trad. Rafeeda & Belial Maudarbux, rev. Ya'qoub Cherif, ISBN 9960-29-429-3 (via archive.org)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "sw" to "Hisn Al-Muslim — «Kinga ya Muislamu katika nyuradi za Qur'ani na hadithi za Mtume ﷺ» — Said bin Ali bin Wahf Al-Qahtani; tafsiri ya Kiswahili: Shafi Abdur-Rahman Omar; Wizara ya Mambo ya Kiislamu ya Saudi Arabia, 1435H/2014M. https://archive.org/details/hisn-al-muslim-kinga-ya-muislamu-katika-nyuradi-za-qurani-na-hadithi-za-mtume-sa_202205", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "اللهم إني أسألك علماً نافعاً، و رزقاً طيباً، و عملاً متقبلاً" to SacredText(
        arabic = "اللهم إني أسألك علماً نافعاً، و رزقاً طيباً، و عملاً متقبلاً",
        transliteration = "Allahumma inni as'aluka ilman nafi'an, wa rizqan tayyiban, wa amalan mutaqabbala",
        transliterations = mapOf("bn" to "আল্লা-হুম্মা ইন্নি আসআলুকা ইলমান নাফে‘আন ওয়া রিয্কান তাইয়্যেবান ওয়া ‘আমালান মুতাক্বাব্বালান"),
        translations = mapOf("en" to "O Allah, I ask You for knowledge that is of benefit, a good provision, and deeds that will be accepted. (Recite in Arabic upon rising in the morning.)", "fr" to "Seigneur, je Te demande de m'accorder une science utile, un bien licite et une œuvre acceptée.", "ur" to "اے اللہ! بے شک میں تجھ سے نفع دینے والے علم کا سوال کرتا ہوں اور پاکیزہ رزق کا اور ایسے عمل کا جو قبول کرلیا جائے۔", "id" to "Ya Allah, sesungguhnya aku mohon kepada-Mu ilmu yang bermanfaat, rezki yang baik dan amal yang diterima.", "fa" to "بار الھا! از تو علم سودمند، رزق پاک و عمل مقبول مسألت مینمایم", "sw" to "Ewe Mwenyezi Mungu na kuomba elimu yenye kunufaisha, na riziki iliyo nzuri, na ibaada yenye kukubaliwa", "ha" to "Ya Allah! Ina rokonka ilimi mai amfani, da arziki na halal, da aiki karbabbe. (Da safe). .)\"", "bn" to "হে আল্লাহ! আমি আপনার নিকট উপকারী জ্ঞান, পবিত্র রিযিক এবং কবুলযোগ্য আমল প্রার্থনা করি।", "tr" to "Allahım! Senden, faydalı bir ilim, helal bir rızık ve kabul olunan bir amel dilerim."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "fr" to "La Citadelle du Musulman, Min. des Affaires islamiques (Riyad), 2005, trad. Rafeeda & Belial Maudarbux, rev. Ya'qoub Cherif, ISBN 9960-29-429-3 (via archive.org)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "sw" to "Hisn Al-Muslim — «Kinga ya Muislamu katika nyuradi za Qur'ani na hadithi za Mtume ﷺ» — Said bin Ali bin Wahf Al-Qahtani; tafsiri ya Kiswahili: Shafi Abdur-Rahman Omar; Wizara ya Mambo ya Kiislamu ya Saudi Arabia, 1435H/2014M. https://archive.org/details/hisn-al-muslim-kinga-ya-muislamu-katika-nyuradi-za-qurani-na-hadithi-za-mtume-sa_202205", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "اللهم بك أصبحنا و بك أمسينا، و بك نحيا و بك نموت، و إليك النشور" to SacredText(
        arabic = "اللهم بك أصبحنا و بك أمسينا، و بك نحيا و بك نموت، و إليك النشور",
        transliteration = "Allahumma bika asbahna wa bika amsayna, wa bika nahya wa bika namut, wa ilaykan-nushur",
        transliterations = mapOf("bn" to "আল্লা-হুম্মা বিকা আসবাহ্না ওয়াবিকা আমসাইনা ওয়াবিকা নাহ্ইয়া, ওয়াবিকা নামূতু ওয়া ইলাইকান নুশূর"),
        translations = mapOf("en" to "O Allah, by You we enter the morning and by You we enter the evening, by You we live and by You we die, and to You is the Final Return. O Allah, You bring us the end of the day as You bring us its beginning, You bring us life and you bring us death, and to You is our fate.", "fr" to "Seigneur Dieu, c'est par Toi que nous sommes en vie au matin, que nous serons au soir, que nous devrons vivre et que nous devrons mourir, vers Toi se fera la résurrection.", "ur" to "اے اللہ! تیری ہی حفاظت میں ہم نے صبح کی اور تیری ہی حفاظت میں شام کی اور تیرے ہی نام پر ہم زندہ ہوتے اور تیرے ہی نام پر ہم مرتے ہیں اور تیری ہی طرف لوٹنا ہے۔", "id" to "Ya Allah, dengan rahmat dan pertolongan-Mu kami memasuki waktu pagi, dan dengan rahmat dan pertolongan-Mu kami memasuki waktu sore. Dengan rahmat dan pertolongan-Mu kami hidup dan dengan kehendak-Mu kami mati. Dan kepada-Mu kebangkitan (bagi semua makhluk).", "fa" to "بار الھا! با لطف تو صبح کردیم، و با عنایت تو به شب رسیدیم، و به خواست تو زندهایم، و به خواست تو میمیریم، و رستاخیز ما بسوی تو است", "sw" to "Ewe Mwenyezi Mungu kwa sababu yako tumeingia katika asubuhi, na kwa ajili yako tumeingia jioni, na kwa ajili yako ndio tumekuwa hai, na kwa ajili yako tutakufa, na kwako tutafufuliwa", "ha" to "Ya Allah, da ikonka ne muka wayi gari kuma da ikonka ne muke shiga maraice, kuma da ikonka ne muke mutuwa kuma gare ka ne taruwa. Wanna idan aka wayi gari kenen. .", "bn" to "হে আল্লাহ! আমরা আপনার জন্য সকালে উপনীত হয়েছি এবং আপনারই জন্য আমরা বিকালে উপনীত হয়েছি। আর আপনার দ্বারা আমরা জীবিত থাকি, আপনার দ্বারাই আমরা মারা যাব, আর আপনার দিকেই উত্থিত হব।", "tr" to "Allahım! Senin (nimetin, koruman ve zikrin) ile sabahlarız ve senin (nimetin, koruman ve zikrin) ile akşamlarız. Senin yardımınla yaşar ve senin yardımınla ölürüz. Ve (kıyâmet günü) dönüş, yalnızca sanadır."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "fr" to "La Citadelle du Musulman, Min. des Affaires islamiques (Riyad), 2005, trad. Rafeeda & Belial Maudarbux, rev. Ya'qoub Cherif, ISBN 9960-29-429-3 (via archive.org)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "sw" to "Hisn Al-Muslim — «Kinga ya Muislamu katika nyuradi za Qur'ani na hadithi za Mtume ﷺ» — Said bin Ali bin Wahf Al-Qahtani; tafsiri ya Kiswahili: Shafi Abdur-Rahman Omar; Wizara ya Mambo ya Kiislamu ya Saudi Arabia, 1435H/2014M. https://archive.org/details/hisn-al-muslim-kinga-ya-muislamu-katika-nyuradi-za-qurani-na-hadithi-za-mtume-sa_202205", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "اللهم إني أسألك العفو و العافية في الدنيا و الآخرة، اللهم إني أسألك العفو و العافية في ديني و دنياي و أهلي و مالي، اللهم أستر عوراتي و أمن روعاتي، اللهم إحفظني من بين يدي و من خلفي ، و عن يميني و عن شمالي، و من فوقي، و أعوذ بعظمتك أن أغتال من تحتي." to SacredText(
        arabic = "اللهم إني أسألك العفو و العافية في الدنيا و الآخرة، اللهم إني أسألك العفو و العافية في ديني و دنياي و أهلي و مالي، اللهم أستر عوراتي و أمن روعاتي، اللهم إحفظني من بين يدي و من خلفي ، و عن يميني و عن شمالي، و من فوقي، و أعوذ بعظمتك أن أغتال من تحتي.",
        transliteration = "((ALLAHUMMA INNII AS-ALUKAL-AF-WA WAL-AAFIYATA FII DDUNIYAA WAL-AAKHIRA, ALLAHUMMA INNII AS-ALUKAL-AF-WA WAL-AAFIYATA FII DIINII WADUNIYAAYA WA-AHALII, WAMAALII, ALLAHUMMA USTUR AURAATII, WA-AAMIN RUU-AATII, ALLAHUMMA IHFAZW-NII MIN BAINI YADAYYA WAMIN KHALFII, WA-AN YAMIINII, WA-AN SHIMAALII, WAMIN FAUQII, WA-AUUDHU BI-ADWAMATIKA AN UGH-TAALA MIN TAH-TII))",
        transliterations = mapOf("bn" to "আল্লা-হুম্মা ইন্নী আসআলুকাল ‘আফওয়া ওয়াল- ‘আ-ফিয়াতা ফিদ্দুনইয়া ওয়াল আ-খিরাতি। আল্লাহুম্মা ইন্নী আসআলুকাল ‘আফওয়া ওয়াল-‘আ-ফিয়াতা ফী দীনী ওয়াদুনইয়াইয়া, ওয়া আহ্লী ওয়া মা-লী, আল্লা-হুম্মাসতুর ‘আওরা-তী ওয়া আমিন রাও‘আ-তি। আল্লা-হুম্মাহফাযনী মিম্বাইনি ইয়াদাইয়্যা ওয়া মিন খালফী ওয়া ‘আন ইয়ামীনী ওয়া শিমা-লী ওয়া মিন ফাওকী। ওয়া আ‘ঊযু বি‘আযামাতিকা আন উগতা-লা মিন তাহ্তী"),
        translations = mapOf("en" to "O Allah, I seek Your forgiveness and Your protection in this world and the next. O Allah, I seek Your forgiveness and Your protection in my religion, in my worldly affairs, in my family and in my wealth. O Allah, conceal my secrets and preserve me from anguish. O Allah, guard me from what is in front of me and behind me, from my left, and from my right, and from above me. I seek refuge in Your Greatness from being struck down from beneath me.", "fr" to "Seigneur je Te demande de m'accorder la bonne santé ici-bas et dans l'au-delà. Ô mon Dieu je Te demande la bonne santé pour ma religion, ma vie d'ici-bas, ma famille et mes biens ; Seigneur dissimule mes défauts et rassure-moi dans ma peur. Ô mon Dieu, protège-moi devant moi, derrière moi, à ma droite, à ma gauche et au-dessus de moi. Je cherche refuge dans Ta grandeur contre le fait d'être englouti dans la terre.", "ur" to "اے اللہ! بے شک میں تجھ سے دنیا اور آخرت میں معافی اور عافیت کا سوال کرتا ہوں، اے اللہ! بے شک میں تجھ سے اپنے دین، اپنی دنیا اور اپنے اہل ومال میں معافی اور عافیت کا سوال کرتا ہوں۔ اے اللہ! میرے عیبوں پر پردہ ڈال دے اور میری گھبراہٹوں میں امن دے، اے اللہ! تو میری حفاظت فرما میرے سامنے سے، میرے پیچھے سے، میری دائیں طرف سے، میری بائیں طرف سے اور میرے اوپر سے۔ اور میں تیری عظمت کے ساتھ اس بات سے پناہ مانگتا ہوں کہ ناگہاں اپنے نیچے سے ہلاک کیا جاؤں۔", "id" to "Ya Allah, sesungguhnya aku mohon kepada-Mu ampunan dan keselamatan di dunia dan akhirat. Ya Allah sesungguhnya aku mohon kepada-Mu ampunan dan keselamatan: dalam agamaku, (kehidupan) duniaku, keluargaku, hartaku. Ya Allah tutuplah auratku (aib dan sesuatu yang tidak layak dilihat orang lain) dan berilah ketentraman di hatiku. Ya Allah, peliharalah aku dari arah depan, belakang, kanan, kiri dan atasku. Aku berlindung dengan kebesaran-Mu, agar aku tidak mendapat bahaya dari bawahku.", "fa" to "الھی! عفو و عافیت دنیا و آخرت را از تو میخواهم. بار الھا! عفو و عافیت دین، دنیا، خانواده و مالم را از تو مسألت مینمایم. بار الھا! عیوب مرا بپوشان و ترس مرا به ایمنی مبدل ساز. الھی! مرا از جلو، پشت سر، سمت راست و چپ و بالای سرم، محافظت بفرما، و به بزرگی و عظمت تو پناه میبرم از اینکه بطور ناگھانی از طرف پایین کشته شوم", "sw" to "Ewe Mwenyezi Mungu na kuomba msamaha na afya duniani na akhera. Ewe Mwenyezi Mungu hakika mimi na kuomba msamaha na afya katika dini yangu, na dunia yangu na jamaa zangu, na mali yangu, Ewe Mwenyezi Mungu nisitiri uchi wangu, na unitulize khofu yangu, Ewe Mwenyezi Mungu ni hifadhi mbele yangu, na nyuma yangu, na kulia kwangu, na kushoto kwangu, na juu yangu, na najilinda kwa utukufu wako kwa kutekwa chini yangu", "ha" to "Ya Allah ina rokonka afuwa da aminci a duniya da lahira, Ya Allah ina rokonka afuwa da aminci daga dukkan mummuna a addinina da duniya ta da iyal ina da dukiya ta. Ya Allah ka kiyaye ni ta gaba na da kuma ta bayana, da ta damana da kuma ta haguna, da kuma ta sama na. Ya Allah ina neman tsarinka da girmanka da a kisfe ni kasa da ni.", "bn" to "হে আল্লাহ! আমি আপনার নিকট দুনিয়া ও আখেরাতে ক্ষমা ও নিরাপত্তা প্রার্থনা করছি। হে আল্লাহ! আমি আপনার নিকট ক্ষমা এবং নিরাপত্তা চাচ্ছি আমার দীন, দুনিয়া, পরিবার ও অর্থ-সম্পদের। হে আল্লাহ! আপনি আমার গোপন ত্রুটিসমূহ ঢেকে রাখুন, আমার উদ্বিগ্নতাকে রূপান্তরিত করুন নিরাপত্তায়। হে আল্লাহ! আপনি আমাকে হিফাযত করুন আমার সামনের দিক থেকে, আমার পিছনের দিক থেকে, আমার ডান দিক থেকে, আমার বাম দিক থেকে এবং আমার উপরের দিক থেকে। আর আপনার মহত্ত্বের উসীলায় আশ্রয় চাই আমার নিচ থেকে হঠাৎ আক্রান্ত হওয়া থেকে", "tr" to "Allahım! Dünya ve âhirette senden af ve âfiyet dilerim. Allahım! Dinim, dünyam, âilem ve malım hakkında senden af ve âfiyet dilerim. Allahım! Ayıplarımı gizle ve beni korkularımdan emin kıl.Allahım! Beni önümden, arkamdan, sağımdan, solumdan ve üstümden (gelecek belâlara karşı) koru. Altımdan yere batırılarak helak edilmekten senin azametine sığınırım."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "fr" to "La Citadelle du Musulman, Min. des Affaires islamiques (Riyad), 2005, trad. Rafeeda & Belial Maudarbux, rev. Ya'qoub Cherif, ISBN 9960-29-429-3 (via archive.org)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "sw" to "Hisn Al-Muslim — «Kinga ya Muislamu katika nyuradi za Qur'ani na hadithi za Mtume ﷺ» — Said bin Ali bin Wahf Al-Qahtani; tafsiri ya Kiswahili: Shafi Abdur-Rahman Omar; Wizara ya Mambo ya Kiislamu ya Saudi Arabia, 1435H/2014M. https://archive.org/details/hisn-al-muslim-kinga-ya-muislamu-katika-nyuradi-za-qurani-na-hadithi-za-mtume-sa_202205", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "يا حي يا قيوم برحمتك أستغيث أصلح لي شأني كله ولا تكلني إلى نفسي طرفة عين" to SacredText(
        arabic = "يا حي يا قيوم برحمتك أستغيث أصلح لي شأني كله ولا تكلني إلى نفسي طرفة عين",
        transliteration = "Ya Hayyu ya Qayyum bi-rahmatika astaghith, aslih li sha'ni kullahu wa la takilni ila nafsi tarfata ayn",
        transliterations = mapOf("bn" to "ইয়া হাইয়্যু ইয়া ক্বাইয়্যূমু বিরহ্মাতিকা আস্তাগীসু, আসলিহ্ লী শা’নী কুল্লাহু, ওয়ালা তাকিলনী ইলা নাফসী ত্বারফাতা ‘আইন"),
        translations = mapOf("en" to "O Ever-Living One, O Eternal One, by Your mercy I call on You to set right all my affairs. Do not place me in charge of my soul even for the blinking of an eye (i.e. a moment).", "fr" to "Ô Vivant, Ô Subsistant, à Toi je demande secours : amende ma situation et ne me laisse point m'en remettre à moi-même, même pour un tout petit moment.", "ur" to "اے زندہ جاوید! اے قائم ودائم! میں تیری ہی رحمت کے ذریعے مدد طلب کرتا ہوں، تو میرا ہر کام سنوار دے اور آنکھ جھپکنے کے برابر بھی مجھے میرے نفس کے سپرد نہ کرنا۔", "id" to "Wahai Yang Maha Hidup dan Maha Terjaga, dengan rahmat-Mu aku minta pertolongan, perbaikilah segala urusanku dan jangan Engkau limpahkan (semua urusan) terhadap diriku walau sekejap mata.", "fa" to "ای زنده و پا برجا! به وسیلۀ رحمت تو از تو کمک میخواهم، همۀ امورم را اصلاح بفرما، و مرا به اندازۀ یک چشم به هم زدن به حال خود رها مکن", "sw" to "Ewe Uliyehai, Uliyesimama kwa dhati yako kwa rehema zako ni nakuomba uniokoe, nitengenezee mambo yangu yote, wala usiniachie mambo yangu mwenyewe (pasina kunisaidia), hata kwa muda (mdogo kama muda) wa kupepesa jicho", "ha" to "Ya (Allah) rayayye, mai tsayuwa da (kansa, wanda komai ya tsayu da shi) da rahamarka na ke neman agaji, ka kyautata mini sha’ani na dukkaninsa, kada ka kyale ni ko da daidai da kyaffawar ido ne . 60", "bn" to "হে চিরঞ্জীব, হে চিরস্থায়ী! আমি আপনার রহমতের অসীলায় আপনার কাছে উদ্ধার কামনা করি, আপনি আমার সার্বিক অবস্থা সংশোধন করে দিন, আর আমাকে আমার নিজের কাছে নিমেষের জন্যও সোপর্দ করবেন না।", "tr" to "Ya Hayy, Ya Kayyûm! Senin rahmetinle yardım dilerim. Bütün işlerimi düzelt ve göz açıp kapayınca kadar -bile olsa- beni nefsime bırakma."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "fr" to "La Citadelle du Musulman, Min. des Affaires islamiques (Riyad), 2005, trad. Rafeeda & Belial Maudarbux, rev. Ya'qoub Cherif, ISBN 9960-29-429-3 (via archive.org)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "sw" to "Hisn Al-Muslim — «Kinga ya Muislamu katika nyuradi za Qur'ani na hadithi za Mtume ﷺ» — Said bin Ali bin Wahf Al-Qahtani; tafsiri ya Kiswahili: Shafi Abdur-Rahman Omar; Wizara ya Mambo ya Kiislamu ya Saudi Arabia, 1435H/2014M. https://archive.org/details/hisn-al-muslim-kinga-ya-muislamu-katika-nyuradi-za-qurani-na-hadithi-za-mtume-sa_202205", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "اللهم عالم الغيب و الشهادة فاطر السماوات و الأرض رب كل شيء و مليكه، أشهد أن لا إله إلا أنت، أعوذ بك من شر الشيطان و شركه، و ان أقترف على نفسي سوءاً أو أجره إلى مسلم." to SacredText(
        arabic = "اللهم عالم الغيب و الشهادة فاطر السماوات و الأرض رب كل شيء و مليكه، أشهد أن لا إله إلا أنت، أعوذ بك من شر الشيطان و شركه، و ان أقترف على نفسي سوءاً أو أجره إلى مسلم.",
        transliteration = "((ALLAHUMMA AALIMAL-GHAIBI WASSHAADAH. FAATWIRA SSAMAAWAATI WAL-ARDHI, RABBA KULLI SHAY-IN WAMALIIKAHU, ASH-HADU AN LAA ILAAHA ILLA ANTA, AUUZHU BIKA MIN SHARRI NAFSII, WAMIN SHARRI SSHAITWAANI WASHIRIKIHI, WA AN AQ-TARIFA ALA NAFSII SUU-AN, AW AJURRAHU ILA MUSLIM))",
        transliterations = mapOf("bn" to "আল্লা-হুম্মা আ-লিমাল গাইবি ওয়াশ্শাহা-দাতি ফা-ত্বিরাস সামা-ওয়াতি ওয়াল আরদ্বি, রব্বা কুল্লি শাই’ইন ওয়া মালীকাহু, আশহাদু আল-লা ইলা-হা ইল্লা আনতা। আ‘উযু বিকা মিন শাররি নাফ্সী ওয়া মিন শাররিশ শাইত্বা-নি ওয়াশিরকিহী/ওয়াশারাকিহী ওয়া আন আক্বতারিফা ‘আলা নাফ্সী সূওআন আউ আজুররাহূ ইলা মুসলিম"),
        translations = mapOf("en" to "O Allah, Knower of the unseen and the evident, Maker of the heavens and the earth, Lord of everything and its Possessor, I bear witness that there is none worthy of worship but You. I seek refuge in You from the evil of my soul, and from the evil of Satan and his helpers. (I seek refuge in You) from bringing evil upon my soul and from harming any Muslim.", "fr" to "Ô mon Dieu ! Toi qui connais ce qui est caché et ce qui est apparent, Créateur des cieux et de la terre, Seigneur et Roi de toute chose, je témoigne qu'il n'y a point de divinité hormis Toi. Je cherche refuge auprès de Toi contre le mal de mon âme et contre le mal du démon et de ce qu'il souffle (en appelant à associer à Dieu), et contre le fait de commettre un mal contre moi-même ou contre un musulman.", "ur" to "اے اللہ! غیب اور حاضر کے جاننے والے! آسمانوں اور زمین کے پیدا کرنے والے! ہر چیز کے رب اور اس کے مالک! میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں۔ میں تیری پناہ میں آتا ہوں اپنے نفس کے شر سے اور شیطان کے شر سے اور اس کے شرک سے اور اس بات سے کہ اپنے ہی خلاف کسی برائی کا ارتکاب کروں یا اسے کسی مسلمان کی طرف کھینچ لاؤں۔", "id" to "Ya Allah, Yang Maha Mengetahui yang ghaib dan yang nyata. Wahai Tuhan Pencipta langit dan bumi, Tuhan segala sesuatu yang merajainya. Aku bersaksi bahwa tiada tuhan yang berhak disembah kecuali Engkau. Aku berlindung kepada-Mu dari kejahatan diriku, setan dan bala tentaranya, atau aku menjalankan kejelekan terhadap diriku atau mendorong orang Islam padanya.", "fa" to "بار الھا! ای دانندۀ نھان و آشکار، آفریدگار آسمان ها و زمین، پروردگار و مالک هر چیز، من گواهی میدهم که بجز تو، معبود دیگری نیست، از شر نفس و از شر شیطان و دام فریبش، و از اینکه خود مرتکب کار بدی شوم و یا به مسلمانی، بدی برسانم، به تو پناه میبرم", "sw" to "Ewe Mwenyezi Mungu, Mjuzi wa yaliyojificha na yaliyowazi, Muumba wa mbingu na ardhi, Mola wa kila kitu, na Mfalme wake, nakiri kwamba hapana mola apasae kuabudiwa kwa haki ila Wewe, najilinda kwako kutokana na shari ya nafsi yangu, na shari ya shetani na shirki yake, na kujichumia uovu kwa nafsi yangu au kumletea muislamu", "ha" to "Ya Allah masanin abunda ke boye da na bayyane, mai kaga halittar sammai da kasa Ubangijin komai kuma mamallakinsa, ina shaidawa babu abin bautawa da cancanta sai kai, kai kadai ina neman tsarinka daga sharrin rai na da kuma sharrin shaidan da shirkansa, da in daukar wa kai ne wani abu mummuna, ko in jawo shi ga wari musulmi. 59", "bn" to "হে আল্লাহ! হে গায়েব ও উপস্থিতের জ্ঞানী, হে আসমানসমূহ ও যমীনের স্রষ্টা, হে সব কিছুর রব্ব ও মালিক! আমি সাক্ষ্য দিচ্ছি যে, আপনি ছাড়া আর কোনো হক্ব ইলাহ নেই। আমি আপনার কাছে আশ্রয় চাই আমার আত্মার অনিষ্ট থেকে, শয়তানের অনিষ্টতা থেকে ও তার শির্ক বা তার ফাাঁদ থেকে, আমার নিজের ওপর কোনো অনিষ্ট করা অথবা কোনো মুসলিমের দিকে তা টেনে নেওয়া থেকে।", "tr" to "Gizli ve âşikarı bilen, göklerin ve yerin yaratıcısı Allahım! Her şeyin Rabbi ve sahibi! Senden başka hak ilah olmadığına şehâdet ederim. Nefsimin şerrinden sana sığınırım. Şeytan ve şirkinin şerrinden, nefsime kötülük etmekten veya o kötülüğü bir müslümana götürmekten sana sığınırım."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "fr" to "La Citadelle du Musulman, Min. des Affaires islamiques (Riyad), 2005, trad. Rafeeda & Belial Maudarbux, rev. Ya'qoub Cherif, ISBN 9960-29-429-3 (via archive.org)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "sw" to "Hisn Al-Muslim — «Kinga ya Muislamu katika nyuradi za Qur'ani na hadithi za Mtume ﷺ» — Said bin Ali bin Wahf Al-Qahtani; tafsiri ya Kiswahili: Shafi Abdur-Rahman Omar; Wizara ya Mambo ya Kiislamu ya Saudi Arabia, 1435H/2014M. https://archive.org/details/hisn-al-muslim-kinga-ya-muislamu-katika-nyuradi-za-qurani-na-hadithi-za-mtume-sa_202205", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "أصبحنا على فطرة الإسلام، و على كلمة الإخلاص، و على دين نبينا محمد صلى الله عليه وسلم، و على ملة أبينا إبراهيم حنيفاً مسلماً و ما كان من المشركين" to SacredText(
        arabic = "أصبحنا على فطرة الإسلام، و على كلمة الإخلاص، و على دين نبينا محمد صلى الله عليه وسلم، و على ملة أبينا إبراهيم حنيفاً مسلماً و ما كان من المشركين",
        transliteration = "((ASW-BAHNAA ALA FITW-RATIL-ISLAAMI WA ALAA KALIMATIL-IKHLAASW, WA ALAA DIINI NABIYYINAA MUHAMMAD -Swala Llahu alaihi wasallam- WA ALAA MILLATI ABIINAA IBRAAHIIM HANIIFAN MUSLIMAN WAMAA KAANA MINAL-MUSH-RIKIIN))",
        transliterations = mapOf("bn" to "আসবাহনা ‘আলা ফিত্বরাতিল ইসলামি ওয়া আলা কালিমাতিল ইখলাসি ওয়া আলা দ্বীনি নাবিয়্যিনা মুহাম্মাদিন সাল্লাল্লা-হু আলাইহি ওয়াসাল্লাম ওয়া আলা মিল্লাতি আবীনা ইবরা-হীমা হানীফাম মুসলিমাও ওয়ামা কা-না মিনাল মুশরিকীন"),
        translations = mapOf("en" to "We have entered a new day 1 upon the natural religion of Islam, the word of sincere devotion, the religion of our Prophet Muhammad (peace and blessings of Allah be upon him), and the faith of our father Ibrahim. He was upright (in worshipping Allah), and a Muslim. He was not of those who worship others besides Allah. 2", "fr" to "Nous sommes au matin sur la fitrah de l'Islam, et sur la parole sincère et suivant la religion de notre Prophète Mohammad ﷺ et de notre père Ibrahim qui était un musulman sincère et n'était pas du nombre des polythéistes.", "ur" to "ہم نے فطرت اسلام، کلمہ اخلاص، اپنے نبی حضرت محمد ﷺ کے دین اور اپنے باپ حضرت ابراہیم علیہ السلام جو یک رخ (اور) فرماں بردار تھے، کی ملت پر صبح کی اور وہ مشرکوں میں سے نہیں تھے۔", "id" to "Di waktu pagi kami memegang agama Islam, kalimat ikhlas, agama nabi kita, Muhammad ﷺ dan agama ayah kami, Ibrahim, yang berdiri di atas jalan yang lurus, muslim dan tidak tergolong orang-orang musyrik.", "fa" to "ما بر فطرت اسلام، کلمۀ اخلاص، دین پیامبرمان محمد ج و آئین پدرمان ابراهیم؛ صبح کردیم، همان ابراهیمی که فقط به سوی حق، تمایل داشت و فرمانبردار خداوند بود، و از مشرکان نبود", "sw" to "Tumeingia asubuhi na maumbile ya kiislamu, na neno la ikhlasi, na dini ya Mtume wetu Muhammad ﷺ na mila (dini) ya baba yetu Ibrahim iliyo sawa hali ya kuwa muislamu wala hakuwa ni mwenye kumshirikisha Mwenyezi Mungu", "ha" to "Mun wayi gari akan halittar da Allah ya yi mana ta musulunci, kuma akan kalmar tauhidi, kuma a kan addinin Annabin mu Muhammad – tsira da amincin Allah su tabbata a gare shi- kuma akan addinin baban mu Ibrahim mai kaucewa dukkan shirka zuwa ga addinin gaskiya mikakken kuma musulmi, bait aba kasancewa daga cikin mushrikai ba. .) (", "bn" to "আমরা সকালে উপনীত হয়েছি ইসলামের ফিত্বরাতের ওপর, নিষ্ঠাপূর্ণ বাণী (তাওহীদ)-এর ওপর, আমাদের নবী মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লামের দীনের ওপর, আর আমাদের পিতা ইবরাহীম আলাইহিস সালামের মিল্লাতের ওপরযিনি ছিলেন একনিষ্ঠ মুসলিম এবং যিনি মুশরিকদের অন্তর্ভুক্ত ছিলেন না", "tr" to "İslâm fıtratı (hak dîni), ihlas kelimesi (kelime-i şehâdet) ve Nebîmiz Muhammed -sallallahu aleyhi ve sellem-'in dini üzere; hanif ve müslüman olan, müşriklerden olmayan babamız İbrahim'in milleti üzere sabahladık."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "fr" to "La Citadelle du Musulman, Min. des Affaires islamiques (Riyad), 2005, trad. Rafeeda & Belial Maudarbux, rev. Ya'qoub Cherif, ISBN 9960-29-429-3 (via archive.org)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "sw" to "Hisn Al-Muslim — «Kinga ya Muislamu katika nyuradi za Qur'ani na hadithi za Mtume ﷺ» — Said bin Ali bin Wahf Al-Qahtani; tafsiri ya Kiswahili: Shafi Abdur-Rahman Omar; Wizara ya Mambo ya Kiislamu ya Saudi Arabia, 1435H/2014M. https://archive.org/details/hisn-al-muslim-kinga-ya-muislamu-katika-nyuradi-za-qurani-na-hadithi-za-mtume-sa_202205", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "اللهم إني أصبحت أشهدك، و أشهد حملة عرشك،  و ملائكتك، و جميع خلقك، أنك أنت الله لا إله إلا أنت وحدك لا شريك لك و أن محمد عبدك و رسولك." to SacredText(
        arabic = "اللهم إني أصبحت أشهدك، و أشهد حملة عرشك،  و ملائكتك، و جميع خلقك، أنك أنت الله لا إله إلا أنت وحدك لا شريك لك و أن محمد عبدك و رسولك.",
        transliteration = "((ALLAHUMMA INNII ASW-BAHTU USH-HIDUKA WA-USH-HIDU HAMALATA ARSHIKA, WAMALAA-IKATAKA WAJAMII-A KHALQIKA, ANNAKA ANTA LLAHU, LAA ILAAHA ILLA ANTA WAHDAKA LAA SHARIIKA LAKA, WA-ANNA MUHAMMADA ABDUKA WARASUULUKA))",
        transliterations = mapOf("bn" to "আল্লা-হুম্মা ইন্নী আসবাহ্তু উশহিদুকা ওয়া উশহিদু হামালাতা ‘আরশিকা ওয়া মালা-ইকাতিকা ওয়া জামী‘আ খালক্বিকা, আন্নাকা আনতাল্লা-হু লা ইলা-হা ইল্লা আনতা ওয়াহ্দাকা লা শারীকা লাকা, ওয়া আন্না মুহাম্মাদান আব্দুকা ওয়া রাসূলুকা"),
        translations = mapOf("en" to "O Allah, I have entered a new morning 1 and call upon You and upon the bearers of Your Throne, upon Your angels and all creation to bear witness that surely You are Allah, there is none worthy of worship but You alone, You have no partners, and that Muhammad is Your slave and Your Messenger. (Recite four times in Arabic.) 2", "fr" to "Seigneur, me voilà au matin témoigner devant Toi, devant ceux qui portent Ton trône, devant Tes Anges et toutes Tes créatures, que c'est Toi qui es Dieu, en dehors de Qui il n'y a point de divinité et que Mohammad est Ton serviteur et Messager. (Quatre fois le matin et le soir.)", "ur" to "اے اللہ! یقیناً میں نے ایسی حالت میں صبح کی کہ تجھے، تیرا عرش اٹھانے والے فرشتوں، تیرے (دیگر) فرشتوں اور تیری تمام مخلوق کو اس بات پر گواہ بناتا ہوں کہ تو ہی اللہ ہے، تیرے سوا کوئی معبود نہیں، تو اکیلا ہے، تیرا کوئی شریک نہیں اور بلا شبہ محمد (ﷺ) تیرے بندے اور تیرے رسول ہیں۔", "id" to "Ya Allah, sesungguhnya aku di waktu pagi bersaksi kepada-Mu, malaikat yang memikul 'Arasy-Mu, malaikat-malaikat dan seluruh makhluk-Mu, sesungguhnya Engkau adalah Allah, tiada Tuhan yang berhak disembah kecuali Engkau Yang Maha Esa, tiada sekutu bagi-Mu dan sesungguhnya Muhammad adalah hamba dan utusan-Mu.", "fa" to "الھی! من در این صبحگاه، تو را و حاملان عرش و تمام فرشتگانت و کلیۀ مخلوقات تو را گواه میگیرم بر این که تو الله هستی، بجز تو معبود دیگری »به حق« وجود ندارد، تو یگانهای و شریکی نداری، و محمد ج بنده و فرستادۀ تو است", "sw" to "Ewe Mwenyezi Mungu hakika mimi nimefika asubuhi na kushuhudia na nina washuhudiza wabeba Arshi yako, na malaika wako, na viumbe vyako vyote, kwamba Wewe ndiye Mwenyezi Mungu hapana apasae kuabudiwa kwa haki ila Wewe, hali ya kuwa peke yako huna mshirika, na kwamba Muhammad ni mja wako, na ni mtume wako", "ha" to "Ya Allah! Ni na wayi gari ina shaida maka, kuma ina shaida wa mala'uku masu dauke da al'afshinka da mala’ikunka, da dukkan halitarka cewa: Kai ne Allah babu abin bautawa da cancanta sai kai, kai kadai kake baaka da abonkin tarayya, kuma hakika (Annabi Muhammad) bawanka ne kuma manzonka ne. (Sau hudu:4). 57 \"", "bn" to "হে আল্লাহ! আমি সকালে উপনীত হয়েছি। আপনাকে আমি সাক্ষী রাখছি, আরও সাক্ষী রাখছি আপনার ‘আরশ বহনকারীদেরকে, আপনার ফিরিশতাগণকে ও আপনার সকল সৃষ্টিকে, (এর উপর) যে- নিশ্চয় আপনিই আল্লাহ, একমাত্র আপনি ছাড়া আর কোনো হক্ব ইলাহ নেই, আপনার কোনো শরীক নেই, আর মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আপনার বান্দা ও রাসূল।", "tr" to "Allahım! Senin, senden başka hak ilah olmayan Allah olduğuna ve Muhammed -sallallahu aleyhi ve sellem-'in de senin kulun ve elçin olduğuna; Seni, senin arşını taşıyanları, meleklerini ve bütün yarattıklarını şahit tutarak sabahladım."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "fr" to "La Citadelle du Musulman, Min. des Affaires islamiques (Riyad), 2005, trad. Rafeeda & Belial Maudarbux, rev. Ya'qoub Cherif, ISBN 9960-29-429-3 (via archive.org)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "sw" to "Hisn Al-Muslim — «Kinga ya Muislamu katika nyuradi za Qur'ani na hadithi za Mtume ﷺ» — Said bin Ali bin Wahf Al-Qahtani; tafsiri ya Kiswahili: Shafi Abdur-Rahman Omar; Wizara ya Mambo ya Kiislamu ya Saudi Arabia, 1435H/2014M. https://archive.org/details/hisn-al-muslim-kinga-ya-muislamu-katika-nyuradi-za-qurani-na-hadithi-za-mtume-sa_202205", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "اللهم ما أصبح بي من نعمة أو بأحد من خلقك، فمنك وحدك لا شريك لك، فلك الحمد و لك الشكر." to SacredText(
        arabic = "اللهم ما أصبح بي من نعمة أو بأحد من خلقك، فمنك وحدك لا شريك لك، فلك الحمد و لك الشكر.",
        transliteration = "((ALLAHUMMA MAA ASW-BAHA BII MIN NI-AMATIN AU BI-AHADIN MINI KHALQIKA FAMINKA WAHDAKA LAA SHARIIKA LAKA, FALAKAL-HAMDU WALAKA ASSHUKUR))",
        transliterations = mapOf("bn" to "আল্লা-হুম্মা মা আসবাহা বী মিন নি‘মাতিন আউ বিআহাদিন মিন খালক্বিকা ফামিনকা ওয়াহ্দাকা লা শারীকা লাকা, ফালাকাল হাম্দু ওয়ালাকাশ্ শুক্রু"),
        translations = mapOf("en" to "O Allah, whatever blessing has been received by me or anyone of Your creation 1 is from You alone, You have no partner. All praise is for you and thanks is to You. 2", "fr" to "Ô mon Dieu, la faveur qui m'a touché ce matin ou a touché une de Tes créatures ne procède que de Toi, Tu n'as aucun associé, à Toi la Louange et à Toi (j'exprime) la reconnaissance.", "ur" to "اے اللہ! صبح کے وقت مجھ پر یا تیری مخلوق میں سے کسی پر جو بھی انعام ہوا ہے، وہ تیری ہی طرف سے ہے۔ تو اکیلا ہے، تیرا کوئی شریک نہیں، پس تیرے ہی لیے سب تعریف ہے اور تیرے ہی لیے شکر ہے۔", "id" to "Ya Allah, nikmat yang kuterima atau diterima oleh seseorang di antara makhluk-Mu di pagi ini adalah dari-Mu. Maha Esa Engkau, tiada sekutu bagi-Mu. Bagi-Mu segala puji dan kepada-Mu panjatan syukur (dari seluruh makhluk-Mu).", "fa" to "الھی! هر نعمتی که در این صبح، شامل حال من یا یکی از مخلوقات شده، از طرف تو بوده است، تو شریکی نداری، پس ستایش و شکر از آن تو است", "sw" to "Ewe Mwenyezi Mungu sikuamka na neema yoyote au kati ya kiumbe chako chochote, na neema ila inatoka kwako, hali ya kuwa peke yake huna mshirika wako, ni zako sifa njema na ni zako shukrani", "ha" to "Allah! Dukkan abin da ya wayi gari nawa na daga ni’ima, ko ga wani daga cikin halattar ka, to daga gare ka ne, kai kadai babu abokin tarayya a gareka, kuma yabo ya tabbata a gareka, kuma godiya ta tabbata a gare ka.", "bn" to "হে আল্লাহ! যে নি‘আমত আমার সাথে সকালে উপনীত হয়েছে, অথবা আপনার সৃষ্টির অন্য কারও সাথে; এসব নি‘আমত কেবল আপনার নিকট থেকেই, আপনার কোনো শরীক নেই। সুতরাং সকল প্রশংসা আপনারই। আর সকল কৃতজ্ঞতা আপনারই প্রাপ্য।", "tr" to "Allahım! Benim veya kullarından birisinin yanında sabaha çıkan her nimet, yalnızca sendendir. Senin ortağın yoktur. Hamd, yalnızca sanadır. Şükür de sanadır."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "fr" to "La Citadelle du Musulman, Min. des Affaires islamiques (Riyad), 2005, trad. Rafeeda & Belial Maudarbux, rev. Ya'qoub Cherif, ISBN 9960-29-429-3 (via archive.org)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "sw" to "Hisn Al-Muslim — «Kinga ya Muislamu katika nyuradi za Qur'ani na hadithi za Mtume ﷺ» — Said bin Ali bin Wahf Al-Qahtani; tafsiri ya Kiswahili: Shafi Abdur-Rahman Omar; Wizara ya Mambo ya Kiislamu ya Saudi Arabia, 1435H/2014M. https://archive.org/details/hisn-al-muslim-kinga-ya-muislamu-katika-nyuradi-za-qurani-na-hadithi-za-mtume-sa_202205", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "يارب لك الحمد كما ينبغي لجلال وجهك، و لعظيم سلطانك." to SacredText(
        arabic = "يارب لك الحمد كما ينبغي لجلال وجهك، و لعظيم سلطانك.",
        transliteration = "Rabbi laka al-hamdu kamā yanbaghī lijalāli wajhika, wa li'azīmi sultānik.",
        translations = mapOf(),
    ),
    "رضيت بالله رباً، و بالإسلام ديناً، و بمحمد صلى الله عليه وسلم نبياً." to SacredText(
        arabic = "رضيت بالله رباً، و بالإسلام ديناً، و بمحمد صلى الله عليه وسلم نبياً.",
        transliteration = "Raditu billahi rabban, wa bil-islami dinan, wa bi Muhammadin sallallahu alayhi wa sallama nabiyya",
        transliterations = mapOf("bn" to "রদ্বীতু বিল্লা-হি রব্বান, ওয়াবিল ইসলা-মি দীনান, ওয়াবি মুহাম্মাদিন সাল্লাল্লা-হু ‘আলাইহি ওয়াসাল্লামা নাবিয়্যান"),
        translations = mapOf("en" to "I am pleased with Allah as my Lord, with Islam as my religion, and with Muhammad (peace and blessings of Allah be upon him) as my Prophet. (Recite three times in Arabic.)", "fr" to "J'ai agréé Dieu comme Seigneur, l'Islam comme religion et Mohammad comme prophète. (trois fois)", "ur" to "میں اللہ کے ساتھ (اس کے) رب ہونے پر راضی ہو گیا اور اسلام کے ساتھ (اس کے) دین ہونے پر اور محمد ﷺ کے ساتھ (ان کے) نبی ہونے پر۔", "id" to "Aku rela Allah sebagai Tuhan-(ku), Islam sebagai agama-(ku) dan Muhammad ﷺ sebagai nabi-(ku).", "fa" to "به ربوبیت الله، و به داشتن دین اسلام، و پیامبری محمد ج راضی و خشنود هستم", "sw" to "Nimeridhia kuwa Mwenyezi Mungu ndie Mola wangu, na uislamu ndio dini yangu, na Muhammad ﷺ kuwa ni mtume wangu", "ha" to "Na yarda da Allah shi ne Ubangiji, da kuma musulunci shi ne addini, da kuma Muhammadu, tsira da amincin Allah su tabbata a gare shi Annabi ne. (Sau Uku:3 ).", "bn" to "আল্লাহকে রব, ইসলামকে দীন ও মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লামকে নবীরূপে গ্রহণ করে আমি সন্তুষ্ট।", "tr" to "Rab olarak Allah'tan, dîn olarak İslam'dan, nebi olarak Muhammed -sallallahu aleyhi ve sellem-'den râzı oldum."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "fr" to "La Citadelle du Musulman, Min. des Affaires islamiques (Riyad), 2005, trad. Rafeeda & Belial Maudarbux, rev. Ya'qoub Cherif, ISBN 9960-29-429-3 (via archive.org)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "sw" to "Hisn Al-Muslim — «Kinga ya Muislamu katika nyuradi za Qur'ani na hadithi za Mtume ﷺ» — Said bin Ali bin Wahf Al-Qahtani; tafsiri ya Kiswahili: Shafi Abdur-Rahman Omar; Wizara ya Mambo ya Kiislamu ya Saudi Arabia, 1435H/2014M. https://archive.org/details/hisn-al-muslim-kinga-ya-muislamu-katika-nyuradi-za-qurani-na-hadithi-za-mtume-sa_202205", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
    ),
    "سبحان الله و بحمده، عدد خلقه، و رضا نفسه ، وزنه عرشه، و مداد كلماته" to SacredText(
        arabic = "سبحان الله و بحمده، عدد خلقه، و رضا نفسه ، وزنه عرشه، و مداد كلماته",
        transliteration = "((SUB-HAANA LLAHI WABIHAMDIHI: ADADA KHALQIHI, WARIDHA NAFSIHI, WAZINATA ARSHIHI WAMIDAADA KALIMAATIH))",
        transliterations = mapOf("bn" to "সুবহা-নাল্ ্ লা-হি ওয়া বিহামদিহী ‘আদাদা খালক্বিহী, ওয়া রিদা নাফসিহী, ওয়া যিনাতা ‘আরশিহী, ওয়া মিদা-দা কালিমা-তিহী"),
        translations = mapOf("en" to "Glory is to Allah and praise is to Him, by the multitude of His creation, by His Pleasure, by the weight of His Throne, and by the extent of His Words. (Recite three times in Arabic upon rising in the morning.)", "fr" to "Gloire et louange à Dieu, autant que le nombre de Ses créatures, de Sa satisfaction, de la pesée de Son trône et la masse d'encre de Ses Paroles (trois fois le matin).", "ur" to "میں اللہ کی پاکیزگی بیان کرتا ہوں اس کی تعریفوں کے ساتھ، اس کی مخلوق کی تعداد کے برابر، اس کی ذات کی رضا کے برابر، اس کے عرش کے وزن اور اس کے کلمات کی روشنائی کے برابر۔", "id" to "Maha Suci Allah, aku memuji-Nya sebanyak makhluk-Nya, sejauh kerelaan-Nya, seberat timbangan 'Arasy-Nya dan sebanyak tinta tulisan kalimat-Nya.", "fa" to "تسبیح و پاکی الله و ستایش او را به تعداد آفریدگانش و خشنودیاش و سنگینی عرشش و جوهر سخنانش، بیان مینمایم", "sw" to "Ametakasika Mwenyezi Mungu, na sifa njema zote ni zake kwa hisabu ya viumbe vyake, na radhi yake, na uzito wa Arshi yake, na wino wa maneno yake", "ha" to "Tsarki ya tabbata ga Allah, tare da yabo a gare shi iya adadin halittar sa, da gwargwadon yardar kansa, da iya nauyin al'arshinsa, da iya yawan tawadar da zata rubuta kalmominsa. (Sau Uku :3 da Safe). .", "bn" to "আমি আল্লাহর প্রশংসাসহ পবিত্রতা ও মহিমা ঘোষণা করছি- তাঁর সৃষ্ট বস্তুসমূহের সংখ্যার সমান, তাঁর নিজের সন্তোষের সমান, তাঁর ‘আরশের ওজনের সমান ও তাঁর বাণীসমূহ লেখার কালি পরিমাণ (অগণিত অসংখ্য)", "tr" to "Yarattıklarının sayısınca, kendisinin râzı olacağı kadar, arşının ağırlığı ve kelimelerinin çokluğunca hamd ederek Allah'ı tüm noksanlıklardan tenzih ederim."),
        sources = mapOf("en" to "Hisn al-Muslim, English translation (thehouseofislam.com)", "fr" to "La Citadelle du Musulman, Min. des Affaires islamiques (Riyad), 2005, trad. Rafeeda & Belial Maudarbux, rev. Ya'qoub Cherif, ISBN 9960-29-429-3 (via archive.org)", "ur" to "Hisnul Muslim (Urdu): 'حصن المسلم: سنت نبوی ﷺ سے ماخوذ اذکار و دعائیں' — official Urdu translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim (AskIslamPedia/AskMadani expanded printing), via islamhouse.com/ur/books/1584/ (PDF: d1.islamhouse.com/data/ur/ih_books/single2/ur_Hisnul_Muslim.pdf). Quranic verses: Fatah Muhammad Jalandhari's Urdu Quran translation via quran.com (resource 234).", "id" to "Hisnul Muslim (Indonesian): 'Kumpulan Doa Dalam Alquran & Hadits' — official Indonesian translation of Sa'id bin Ali Al-Qahtani's Hisnul Muslim, via islamhouse.com/id/books/1089/. Quranic verses: Indonesian Ministry of Religious Affairs (Kemenag) Quran translation via quran.com (resource 33).", "fa" to "«پناهگاه مسلمان [حصن المسلم]» — سعید بن علی بن وهف القحطانی؛ ترجمۀ فارسی: د. یونس یزدانپرست؛ اسلام‌هاوس (islamhouse.com/fa)، کتاب شمارۀ 647. ‏PDF: https://d1.islamhouse.com/data/fa/ih_books/single/fa_hisn_muslim.pdf", "sw" to "Hisn Al-Muslim — «Kinga ya Muislamu katika nyuradi za Qur'ani na hadithi za Mtume ﷺ» — Said bin Ali bin Wahf Al-Qahtani; tafsiri ya Kiswahili: Shafi Abdur-Rahman Omar; Wizara ya Mambo ya Kiislamu ya Saudi Arabia, 1435H/2014M. https://archive.org/details/hisn-al-muslim-kinga-ya-muislamu-katika-nyuradi-za-qurani-na-hadithi-za-mtume-sa_202205", "ha" to "Garkuwar Musulmi — Na: Dr. Said bin Aliyu bn Wahaf Alkahtani; Fassarar: Salihu Abdullahi Abubakar; Wanda ya duba: Aliyu Muhammad Sadisu (1436 AH; Islam House, littafi na 411806)", "bn" to "হিসনুল মুসলিম [মুসলিমের দুর্গ] — সা‘ঈদ ইবন আলী ইবন ওয়াহাফ আলক্বাহত্বানী; অনুবাদ ও সম্পাদনা: ড. আবু বকর মুহাম্মাদ যাকারিয়া (Islam House, বই নং 1588)", "tr" to "Hısnul-Müslim (Türkçe): Kur'an ve Sünnette Müslümanın Sığınağı — Dua ve Zikirler. Müellif: Saîd b. Ali el-Kahtânî; çeviren: İsmail Yaşa; tashih: Muhammed Şahin. islamhouse.com (Turkish section), https://islamhouse.com/tr/books/861 (tam metin aynası: https://byenah.com/tr/discover-islam/8773)."),
